	@Test
	@Timeout(value = 20, unit = TimeUnit.SECONDS)
	void actualTripleMapGrowthRevokesTheAdmittedRead(@TempDir Path root) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc")
				.setTripleDBSize(8L * 1024L * 1024L)
				.setMapGrowthReadDrainTimeoutMillis(0L)
				.setAutoGrow(true)
				.setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(32L * 1024L * 1024L)
				.setFrontierHeapBudgetBytes(32L * 1024L * 1024L);
		LmdbStore store = new LmdbStore(root.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 10, TimeUnit.SECONDS);
			var values = SimpleValueFactory.getInstance();
			var type = values.createIRI("urn:publication-growth:type");
			try (var writer = repository.getConnection()) {
				writer.add(values.createIRI("urn:publication-growth:s"), RDF.TYPE, type);
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			LmdbSailStore backing = store.getBackingStore();
			try (var admission = backing.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null);
					SailDataset dataset = backing.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ)) {
				var source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
				var statistics = (LmdbEvaluationStatistics) backing.getEvaluationStatistics();
				var strategy = store.getConnectionEvaluationStrategyFactory()
						.createEvaluationStrategy(null, source, statistics, store.getQueryExecutionPolicy());
				var pipeline = new LmdbQueryOptimizerPipeline(strategy, source, statistics);
				var query = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
						"SELECT ?s WHERE { ?s a <urn:publication-growth:type> }", null).getTupleExpr();
				Object writerOwner = new Object();
				LmdbSailStore.MapGrowthObserver noReplay = (kind, token, deadline, attempts, views) -> false;
				try (var writer = backing.registerReadAttempt(writerOwner, noReplay)) {
					writer.markWriteIntent();
					try {
						pipeline.withPreparedQueryEntry(query, null, EmptyBindingSet.getInstance(),
								(prepared, cascades) -> {
									PreparedLeafCall call = PackedCostTestSupport.preparedLeaf(prepared);
									var model = new LmdbPackedCostModel(statistics.estimatorRuntime(),
											source.getSnapshotEpoch(),
											true, source, strategy);
									try (PackedCostSession session = model.openSession(call.query())) {
										assertInstanceOf(LmdbFrontierStatisticsCostSession.class, session);
										assertMappedRows(session, call, 1L);
										TripleStore triples = backing.getTripleStore();
										long oldSize = triples.mapSizeBytes();
										org.junit.jupiter.api.Assertions.assertDoesNotThrow(() -> {
											try (var warning = backing.beginMapGrowthWarning(writerOwner);
													var emergency = backing.beginMapGrowthAttempt(writerOwner)) {
												emergency.requestQuiescence(LmdbSailStore.MapResizeKind.TRIPLE_STORE);
												assertTrue(triples.growMapForEstimatedWrite(oldSize, emergency));
											}
										});
										assertTrue(triples.mapSizeBytes() > oldSize,
												"the control must perform a real native remap");
										assertThrows(IllegalStateException.class, () -> estimate(session, call),
												"an invalidated native read cannot retain mapped authority");
									}
									return null;
								});
					} finally {
						writer.completeTransaction();
					}
				}
			}
		} finally {
			repository.shutDown();
		}
	}

