	private static PackedCostEstimate estimate(PackedCostSession session, PreparedLeafCall call) {
		PackedCostEstimate result = new PackedCostEstimate();
		session.estimateLeaf(call.relationId(), call.emptyContext(), result);
		return result;
	}

	private static double assertMappedRows(PackedCostSession session, PreparedLeafCall call, long expectedRows) {
		return assertMappedRows(estimate(session, call), expectedRows);
	}

	private static double assertMappedRows(PackedCostEstimate result, long expectedRows) {
		assertEquals((double) expectedRows, result.outputRows(), result.estimateSource());
		assertTrue(result.estimateSource().startsWith("frontier-v2"), result.estimateSource());
		assertTrue(result.evidenceStateId() > 0, "the actual mapped state must remain attached");
		assertNotNull(result.evidenceGuarantee());
		assertNotNull(result.evidenceDisposition());
		assertTrue(result.hasExplicitPhysicalCost(), "the actual physical access must remain priced");
		assertTrue(Double.isFinite(result.accessRows()), "the physical access population must remain known");
		double generation = result.plannedDoubleMetric("plannedFrontierGenerationId", -1.0d);
		assertTrue(generation > 0.0d, "the estimate must retain the admitted mapped generation");
		return generation;
	}

	private static void assertSameEvidenceAndCost(PackedCostEstimate expected, PackedCostEstimate actual) {
		assertEquals(expected.estimateSource(), actual.estimateSource());
		assertEquals(expected.evidenceGuarantee(), actual.evidenceGuarantee());
		assertEquals(expected.evidenceDisposition(), actual.evidenceDisposition());
		assertEquals(expected.plannedDoubleMetric("plannedFrontierGenerationId", -1.0d),
				actual.plannedDoubleMetric("plannedFrontierGenerationId", -1.0d));
		assertEquals(expected.plannedDoubleMetric("plannedFrontierLowerRows", -1.0d),
				actual.plannedDoubleMetric("plannedFrontierLowerRows", -1.0d));
		assertEquals(expected.plannedDoubleMetric("plannedFrontierUpperRows", -1.0d),
				actual.plannedDoubleMetric("plannedFrontierUpperRows", -1.0d));
		assertEquals(expected.hasExplicitPhysicalCost(), actual.hasExplicitPhysicalCost());
		assertEquals(expected.accessRows(), actual.accessRows());
		assertEquals(expected.invocations(), actual.invocations());
		assertEquals(expected.sequentialRows(), actual.sequentialRows());
		assertEquals(expected.randomSeeks(), actual.randomSeeks());
		assertEquals(expected.iteratorOpens(), actual.iteratorOpens());
		assertEquals(expected.indexName(), actual.indexName());
		assertEquals(expected.accessMode(), actual.accessMode());
		assertEquals(expected.lookupComponentMask(), actual.lookupComponentMask());
	}
